async function main() {
  console.log("── VAPT seed: clearing previous data ──");
  await db.vaptVulnerability.deleteMany();
  await db.vaptScan.deleteMany();
  await db.vaptAsset.deleteMany();
  await db.vaptCustomCheck.deleteMany();
  await db.vaptScope.deleteMany();
  await db.vaptCredential.deleteMany();
  await db.vaptDiscovery.deleteMany();
  // Remove mirror scans from earlier seed runs (promotion containers).
  await db.scan.deleteMany({ where: { mode: "vapt" } });

  const orgs = await db.organization.findMany();
  const byName = (n: string) => orgs.find((o) => o.name.toLowerCase().includes(n.toLowerCase()));
  const orgMap: Record<string, NonNullable<ReturnType<typeof byName>>> = {};
  for (const key of Object.keys(ORG_SPEC)) {
    const org = byName(key === "CBE" ? "Commercial Bank" : key);
    if (!org) {
      console.log(`  ? ${key} not found — run prisma/seed.ts first.`);
      return;
    }
    orgMap[key] = org;
  }
  const officer = await db.user.findFirst({ where: { organizationId: orgMap.CBE.id, role: "ORG_ADMIN" } });
  // Four-eyes: the approving user must be a DIFFERENT user in the org — use
  // the compliance officer (seed-users guarantees one per pilot org).
  const approver = (await db.user.findFirst({ where: { organizationId: orgMap.CBE.id, role: "COMPLIANCE_OFFICER" } }))
    ?? (await db.user.findFirst({ where: { organizationId: orgMap.CBE.id, role: "ORG_ADMIN" } }));

  // ── 1. Attack-surface registry ─────────────────────────────────────────────
  console.log("── Attack-surface registry (EASM) ──");
  const assetIds: Record<string, { id: string; spec: AssetSpec; orgId: string }> = {};
  for (const [orgKey, specs] of Object.entries(ORG_SPEC)) {
    const org = orgMap[orgKey];
    for (const spec of specs) {
      const a = await db.vaptAsset.create({
        data: {
          organizationId: org.id,
          name: spec.name,
          kind: spec.kind,
          identifier: spec.identifier,
          environment: spec.environment,
          surface: spec.surface,
          criticality: spec.criticality,
          osOrPlatform: spec.platform ?? KIND_PLATFORMS[spec.kind as keyof typeof KIND_PLATFORMS]?.[0] ?? null,
          tags: JSON.stringify(spec.tags ?? []),
          managed: spec.managed ?? true,
          notes: spec.notes ?? null,
          firstSeenAt: ago(90),
          lastSeenAt: ago(2),
        },
      });
      assetIds[`${orgKey}/${spec.name}`] = { id: a.id, spec, orgId: org.id };
    }
  }
  const assetCount = Object.keys(assetIds).length;
  console.log(`  + ${assetCount} asset(s) across ${Object.keys(ORG_SPEC).length} organizations (incl. 1 shadow-IT discovery)`);

  // ── 1b. Vulnerable lab-target assets (true-functionality demo — the REAL
  //        engine detects them when mini-services/vuln-lab is running) ─────
  const labAssets: AssetSpec[] = [
    { name: "VULN-LAB web app (Apache 2.4.49 banner)", kind: "WEBAPP", identifier: "http://127.0.0.1:3060", environment: "DEV", surface: "INTERNAL", criticality: "medium", platform: "Apache httpd 2.4.49 (lab)", tags: ["lab", "vulnerable-by-design"] },
    { name: "VULN-LAB multi-service host", kind: "SERVER", identifier: "127.0.0.1", environment: "DEV", surface: "INTERNAL", criticality: "medium", platform: "Mixed lab services (vsftpd/ProFTPD/OpenSSH/Redis)", tags: ["lab", "vulnerable-by-design"] },
    // Protocol labs (mini-services/vuln-lab/protocol-labs.ts) for the
    // credentialed-audit engines: SNMP v1/v2c/v3, MongoDB no-auth + SCRAM,
    // MariaDB with mysql_native_password auth.
    // No snmp-v3 credential by design: the engine's RFC 3412 probe uses the
    // anonymous noAuthNoPriv security level, and this legacy lab device
    // answers it — the misconfig finding the acceptance test asserts.
    { name: "VULN-LAB SNMP device (udp/3161)", kind: "NETWORK", identifier: "127.0.0.1:3161", environment: "DEV", surface: "INTERNAL", criticality: "medium", platform: "Cisco IOS 12.2(55)SE5 (lab)", tags: ["lab", "vulnerable-by-design"] },
    { name: "VULN-LAB MongoDB no-auth (tcp/3160)", kind: "DATABASE", identifier: "127.0.0.1:3160", environment: "DEV", surface: "INTERNAL", criticality: "medium", platform: "MongoDB 4.0 (lab)", tags: ["lab", "vulnerable-by-design"] },
    { name: "VULN-LAB MariaDB (tcp/3162)", kind: "DATABASE", identifier: "127.0.0.1:3162", environment: "DEV", surface: "INTERNAL", criticality: "medium", platform: "MariaDB 5.5 (lab)", tags: ["lab", "vulnerable-by-design"], credentials: [{ kind: "mysql", username: "audit", secret: "AdwaAudit2026!" }] },
    { name: "VULN-LAB MongoDB SCRAM auth (tcp/3164)", kind: "DATABASE", identifier: "127.0.0.1:3164", environment: "DEV", surface: "INTERNAL", criticality: "medium", platform: "MongoDB 5.0 (lab)", tags: ["lab", "vulnerable-by-design"], credentials: [{ kind: "mongo", username: "audit", secret: "AdwaAudit2026!" }] },
  ];
  let credCount = 0;
  for (const spec of labAssets) {
    const a = await db.vaptAsset.create({
      data: {
        organizationId: orgMap.CBE.id,
        name: spec.name, kind: spec.kind, identifier: spec.identifier,
        environment: spec.environment, surface: spec.surface, criticality: spec.criticality,
        osOrPlatform: spec.platform, tags: JSON.stringify(spec.tags ?? []),
        managed: true,
        notes: "Intentionally vulnerable lab target (mini-services/vuln-lab) — for engine acceptance tests only",
        firstSeenAt: ago(30), lastSeenAt: ago(0),
      },
    });
    // Scan credentials — AES-256-GCM at rest (plan §1 envelope encryption).
    for (const c of spec.credentials ?? []) {
      if (c.kind === "snmp-v3") {
        // USM principal only (the engine probes noAuthNoPriv security level)
        await db.vaptCredential.create({ data: { assetId: a.id, kind: c.kind, username: c.username, secretCiphertext: encryptSecret("(noAuthNoPriv probe)") } });
      } else if (c.secret) {
        await db.vaptCredential.create({ data: { assetId: a.id, kind: c.kind, username: c.username, secretCiphertext: encryptSecret(c.secret) } });
      }
      credCount++;
    }
    assetIds[`CBE/${spec.name}`] = { id: a.id, spec, orgId: orgMap.CBE.id };
  }
  console.log(`  + ${labAssets.length} vulnerable lab-target asset(s) (CBE, engine acceptance)${credCount ? ` + ${credCount} encrypted scan credential(s)` : ""}`);

  // ── 1c. Authorization scopes (the plan §1 gate — APPROVED via four-eyes) ─
  console.log("── Authorization scopes (four-eyes) ──");
  const officerEmail = officer?.email ?? "admin@cbe.com.et";
  const approverEmail = approver?.email ?? "ciso@cbe.com.et";
  const scopeSpecs = [
    {
      name: "CBE internal & perimeter scope",
      targets: [
        { kind: "cidr", value: "10.0.0.0/8" },
        { kind: "domain", value: "cbe.com.et" },
        { kind: "domain", value: "localhost" },
        { kind: "ip", value: "127.0.0.1" },
        { kind: "url", value: "http://localhost:3000" },
      ],
      owner: "CBE Technology Infrastructure — Ato Bekele (CTO office)",
      authorizationNote: "CISO written authorization ICT-SEC-2026-114: recurring quarterly VAPT over the registered estate, approved by the security committee 2026-10-12.",
      validFrom: ago(30), validUntil: new Date(Date.now() + 335 * 86_400_000),
      intrusiveAllowed: false,
    },
  ];
  for (const spec of scopeSpecs) {
    const sc = await db.vaptScope.create({
      data: {
        organizationId: orgMap.CBE.id,
        name: spec.name,
        targets: JSON.stringify(spec.targets),
        owner: spec.owner,
        authorizationNote: spec.authorizationNote,
        validFrom: spec.validFrom,
        validUntil: spec.validUntil,
        status: "APPROVED",
        intrusiveAllowed: spec.intrusiveAllowed,
        requestedById: officer?.id ?? "seed",
        approvedById: (approver?.id ?? officer?.id) ?? null,
        approvedAt: ago(29),
      },
    });
    console.log(`  + scope "${sc.name}" APPROVED (requested ${officerEmail}, approved ${approverEmail}, four-eyes=${sc.requestedById !== sc.approvedById})`);
  }
  // Dashen: a scope covering only a /24 — for the out-of-scope rejection demo.
  const dashenScope = await db.vaptScope.create({
    data: {
      organizationId: orgMap.Dashen.id,
      name: "Dashen DMZ segment scope (partial)",
      targets: JSON.stringify([{ kind: "cidr", value: "10.9.0.0/24" }]),
      owner: "Dashen IT Operations",
      authorizationNote: "Written authorization DIT-2026-077 covering the DMZ /24 only.",
      validFrom: ago(20), validUntil: new Date(Date.now() + 340 * 86_400_000),
      status: "APPROVED",
      requestedById: officer?.id ?? "seed",
      approvedById: approver?.id ?? null,
      approvedAt: ago(19),
    },
  });
  console.log(`  + Dashen scope "${dashenScope.name}" APPROVED (covers 10.9.0.0/24 only — out-of-scope rejections demonstrable)`);

  // ── 1e. EASM discoveries — REAL captured certificate-transparency + DNS
  //        data (scripts/assets/easm-cbe-fixture.json: live crt.sh capture +
  //        live A-record resolution for cbe.com.et — public passive OSINT).
  //        None of these hostnames are registered assets → the tender's
  //        "unmanaged / shadow-IT" EASM signal, with real evidence.
  console.log("── EASM discoveries (real CT-log capture: cbe.com.et) ──");
  try {
    const fixture = JSON.parse(readFileSync(join(__dirname, "assets/easm-cbe.com.et-fixture.json"), "utf8")) as {
      asOf: string; domain: string;
      hosts: { name: string; ct: { entryId: number; issuer: string; notBefore?: string }; ipAddresses: string[]; resolved: boolean }[];
    };
    for (const h of fixture.hosts) {
      await db.vaptDiscovery.create({
        data: {
          organizationId: orgMap.CBE.id,
          domain: fixture.domain,
          name: h.name,
          ipAddresses: JSON.stringify(h.ipAddresses),
          sources: JSON.stringify([{ ct: h.ct }]),
          resolved: h.resolved,
          inScope: true, // the approved CBE scope covers the cbe.com.et zone
          managed: false, // none of these hostnames are registered assets → shadow-IT
          firstSeenAt: ago(3),
          lastSeenAt: ago(0),
        },
      });
    }
    const resolving = fixture.hosts.filter((h) => h.resolved).length;
    console.log(`  + ${fixture.hosts.length} discovered hostname(s) under ${fixture.domain} (${resolving} resolving, all unmanaged/shadow) — CT capture as of ${fixture.asOf}`);
  } catch (e) {
    console.log(`  ? EASM fixture not loaded (${(e as Error).message}) — discovery registry left empty`);
  }

  // ── 1d. Sample custom check (declarative YAML, sandboxed) ───────────────
  const sampleCheck = await db.vaptCustomCheck.create({
    data: {
      organizationId: orgMap.CBE.id,
      name: "Legacy FTP banner disclosure",
      yaml: [
        "name: Legacy FTP banner disclosure",
        "severity: medium",
        "title: FTP greeting discloses product and version",
        "remediation: Strip product/version details from the FTP greeting banner.",
        "match:",
        "  - type: banner-regex",
        '    pattern: "220[ -].*(ProFTPD|vsFTPd|vsftpd) [0-9.]+"',
        "",
      ].join("\n"),
      enabled: true,
      createdById: officer?.id ?? null,
    },
  });
  console.log(`  + sample custom check "${sampleCheck.name}" (banner-regex matcher)`);

  // ── 2. Scan runs (engine-labelled, honest) ────────────────────────────────
  console.log("── Scan runs ──");
  const scans: { id: string; orgId: string; key: string }[] = [];
  for (const [orgKey, org] of Object.entries(orgMap)) {
    for (const [i, scanSpec] of ([
      { name: "Q3 infrastructure assessment", type: "INFRA", days: 43, salt: 1 },
      { name: "Quarterly perimeter sweep", type: "FULL", days: 9, salt: 2 },
    ] as const).entries()) {
      const scan = await db.vaptScan.create({
        data: {
          organizationId: org.id,
          name: scanSpec.name,
          scanType: scanSpec.type,
          status: "COMPLETED",
          engineMode: "simulated",
          targetCount: ORG_SPEC[orgKey].length,
          createdById: orgKey === "CBE" ? officer?.id ?? null : null,
          startedAt: ago(scanSpec.days),
          completedAt: ago(scanSpec.days, -0.2),
          durationMs: 4_200 + i * 900,
          detail: "Engine: reference catalogue (decision D3 — honestly labelled). Live DAST runs when an analyst launches one against a web target.",
        },
      });
      scans.push({ id: scan.id, orgId: org.id, key: `${orgKey}/${scanSpec.name}` });
      if (orgKey === "CBE" && scanSpec.type === "FULL") {
        // The most recent CBE scan is the hybrid one (live DAST ran).
        await db.vaptScan.update({ where: { id: scan.id }, data: { engineMode: "hybrid", dastReal: true } });
      }
    }
  }
  console.log(`  + ${scans.length} completed scan run(s)`);

  const scanForOrg = (orgId: string) => scans.filter((s) => s.orgId === orgId);
  const latestScan = (orgId: string) => scanForOrg(orgId).sort((a, b) => a.id.localeCompare(b.id))[0]?.id ?? null;

  // ── 3. Vulnerabilities (engine-generated, then curated headliners) ────────
  console.log("── Vulnerabilities ──");
  let vulnCount = 0;
  const createdVulns: { id: string; orgKey: string; assetName: string; severity: string; cveId: string | null; organizationId: string; assetId: string }[] = [];

  for (const [orgKey, org] of Object.entries(orgMap)) {
    const orgAssets = Object.entries(assetIds).filter(([k]) => k.startsWith(`${orgKey}/`));
    for (const [key, entry] of orgAssets) {
      const drafts = buildSimulatedFindings(
        {
          id: entry.id,
          kind: entry.spec.kind,
          osOrPlatform: entry.spec.platform ?? null,
          criticality: entry.spec.criticality,
          surface: entry.spec.surface,
          environment: entry.spec.environment,
        },
        3
      );
      for (const draft of drafts) {
        const severity = severityFromCvss(draft.cvssScore);
        const { score, priorityClass } = prioritise({
          cvssScore: draft.cvssScore, epss: draft.epss, kev: draft.kev,
          assetCriticality: entry.spec.criticality, assetSurface: entry.spec.surface, assetEnvironment: entry.spec.environment,
        });
        const detectedAt = draft.detectedAt;
        // Status realism: older low/medium findings are mostly remediated.
        const roll = (detectedAt.getTime() / 3600_000) % 10;
        let status = "open";
        let remediatedAt: Date | null = null;
        if (severity === "low" || severity === "medium") {
          if (roll < 6) {
            status = "remediated";
            const due = vaptSlaDueDate(severity, detectedAt);
            // two-thirds closed on time, one-third late (honest mix)
            remediatedAt = roll < 4 ? new Date(due.getTime() - 2 * DAY) : new Date(due.getTime() + 6 * DAY);
          } else if (roll < 7) status = "in_progress";
          else if (roll < 8) status = "accepted";
        } else if (severity === "high" && roll < 2) {
          status = "remediated";
          remediatedAt = new Date(detectedAt.getTime() + 12 * DAY);
        }
        const v = await db.vaptVulnerability.create({
          data: {
            organizationId: org.id,
            assetId: entry.id,
            scanId: latestScan(org.id),
            cveId: draft.cveId,
            title: draft.title,
            description: draft.description,
            remediation: draft.remediation,
            category: draft.category,
            severity,
            cvssScore: draft.cvssScore,
            cvssVector: draft.cvssVector ?? null,
            epss: draft.epss,
            kev: draft.kev,
            priorityScore: score,
            priorityClass,
            evidence: JSON.stringify(draft.evidence),
            status,
            dueAt: vaptSlaDueDate(severity, detectedAt),
            remediatedAt,
            detectedAt,
          },
        });
        createdVulns.push({ id: v.id, orgKey, assetName: entry.spec.name, severity, cveId: draft.cveId, organizationId: org.id, assetId: entry.id });
        vulnCount++;
      }
    }
  }

  // Curated headliners — replace a same-asset same-CVE auto finding if present,
  // else create; then apply the curated status/dates.
  for (const c of CURATED) {
    const entry = assetIds[`${c.org}/${c.asset}`];
    if (!entry) continue;
    // Heuristic entries (cveId null) look the catalogue up by title.
    const catalogue = c.cveId
      ? VAPT_CATALOGUE.find((e: CatalogueEntry) => e.cveId === c.cveId)
      : VAPT_CATALOGUE.find((e: CatalogueEntry) => e.title.startsWith("TLS 1.0/1.1 enabled"));
    if (!catalogue) continue;
    const detectedAt = ago(c.extra?.days ?? 5);
    const severity = severityFromCvss(catalogue.cvssScore);
    const { score, priorityClass } = prioritise({
      cvssScore: catalogue.cvssScore, epss: catalogue.epss, kev: catalogue.kev,
      assetCriticality: entry.spec.criticality, assetSurface: entry.spec.surface, assetEnvironment: entry.spec.environment,
    });
    const dueAt = vaptSlaDueDate(severity, detectedAt);
    let status = c.extra?.status ?? "open";
    let remediatedAt: Date | null = null;
    if (status === "remediated") remediatedAt = ago(c.extra?.remediatedDaysAgo ?? 3);
    // Delete any auto-generated duplicate for the same asset+finding (curated
    // wins) — and drop the stale handle from createdVulns so promotion picks
    // the curated record, never a deleted id.
    await db.vaptVulnerability.deleteMany({ where: { assetId: entry.id, ...(c.cveId ? { cveId: c.cveId } : { title: catalogue.title }) } });
    for (let i = createdVulns.length - 1; i >= 0; i--) {
      const v = createdVulns[i];
      const same = v.assetId === entry.id && (c.cveId ? v.cveId === catalogue.cveId : v.assetName === entry.spec.name && v.cveId === null);
      if (same) createdVulns.splice(i, 1);
    }
    const created = await db.vaptVulnerability.create({
      data: {
        organizationId: orgMap[c.org].id,
        assetId: entry.id,
        scanId: latestScan(orgMap[c.org].id),
        cveId: catalogue.cveId, title: catalogue.title, description: catalogue.description, remediation: catalogue.remediation,
        category: catalogue.category, severity, cvssScore: catalogue.cvssScore, cvssVector: catalogue.cvssVector ?? null,
        epss: catalogue.epss, kev: catalogue.kev, priorityScore: score, priorityClass,
        evidence: JSON.stringify({ mode: "simulated", basis: "Bundled NVD/CISA reference catalogue (decision D3 — honestly labelled)", curated: "seed headliner", osOrPlatform: entry.spec.platform ?? null }),
        status, dueAt, remediatedAt, detectedAt,
      },
    });
    createdVulns.push({ id: created.id, orgKey: c.org, assetName: entry.spec.name, severity, cveId: catalogue.cveId, organizationId: orgMap[c.org].id, assetId: entry.id });
    vulnCount++;
  }
  console.log(`  + ${vulnCount} vulnerability record(s) (engine-generated + curated headliners)`);

  // One risk-accepted finding with a recorded justification (audit-realistic).
  const acceptCandidate = await db.vaptVulnerability.findFirst({
    where: { severity: "medium", status: "open", organizationId: orgMap.CBE.id },
    orderBy: { priorityScore: "desc" },
  });
  if (acceptCandidate) {
    await db.vaptVulnerability.update({
      where: { id: acceptCandidate.id },
      data: {
        status: "accepted",
        description: `${acceptCandidate.description}\n\nRisk acceptance: compensating control in place (WAF rule + segmentation) — re-evaluated quarterly by the security committee.`,
      },
    });
  }

  // ── 4. Promotion into the Findings module (SLA/banner integration) ───────
  console.log("── Promoting criticals into the Findings module ──");
  const rule = await db.rule.findFirst({ where: { code: "NBE-22", isActive: true } });
  if (!rule) throw new Error("NBE-22 anchor rule missing — run db:seed first");

  const promoteTargets = createdVulns
    .filter((v) => v.orgKey === "CBE" && v.severity === "critical" && v.status === "open")
    .sort((a, b) => (a.cveId ?? "").localeCompare(b.cveId ?? ""))
    .slice(0, 4);

  // Guarantee the four flagship promotions exist on the curated story assets
  // (Log4Shell on the middleware node, PAN-OS on the perimeter firewall,
  // Zerologon on the legacy DC, ProxyLogon on the Exchange server).
  const wanted: { cveId: string; asset: string }[] = [
    { cveId: "CVE-2021-44228", asset: "Middleware / integration node" },
    { cveId: "CVE-2024-3400", asset: "Perimeter firewall cluster A" },
    { cveId: "CVE-2020-1472", asset: "Domain controller 02 (legacy)" },
    { cveId: "CVE-2021-26855", asset: "Exchange mail server" },
  ];
  const finalTargets = wanted
    .map(({ cveId, asset }) =>
      createdVulns.find((v) => v.orgKey === "CBE" && v.cveId === cveId && v.assetName === asset)
        ?? createdVulns.find((v) => v.orgKey === "CBE" && v.cveId === cveId)
        ?? promoteTargets.find((p) => p.cveId === cveId)
    )
    .filter((v): v is NonNullable<typeof v> => Boolean(v))
    .slice(0, 4);

  for (const target of finalTargets) {
    const v = await db.vaptVulnerability.findUnique({ where: { id: target.id }, include: { asset: true } });
    if (!v) continue;
    const label = v.cveId ?? v.title.slice(0, 48);
    const mirrorScan = await db.scan.create({
      data: {
        organizationId: v.organizationId,
        frameworkId: rule.frameworkId ?? null,
        name: `VAPT ▸ ${label} — ${v.asset.name}`,
        mode: "vapt",
        status: "complete",
        auditorName: "Adwa VAPT Engine",
        overallScore: null,
        pillarScores: null,
        findingsCount: 1,
        criticalFindings: v.severity === "critical" ? 1 : 0,
        startedAt: v.detectedAt,
        completedAt: v.detectedAt,
        durationMinutes: 0,
      },
    });
    const finding = await db.scanResult.create({
      data: {
        scanId: mirrorScan.id,
        ruleId: rule.id,
        answer: "no",
        answeredAt: v.detectedAt,
        score: 0,
        riskRank: v.priorityScore,
        findingEn: `VAPT ${label} — ${v.title} (asset: ${v.asset.name}, CVSS ${v.cvssScore.toFixed(1)}, priority ${v.priorityScore.toFixed(1)}/100${v.kev ? ", CISA KEV" : ""})`,
        findingAm: `VAPT ${label} — በ${v.asset.name} ላይ የተገኘ የደህንነት ብልሽት (CVSS ${v.cvssScore.toFixed(1)})`,
        status: "open",
        dueAt: v.dueAt,
        vaptVulnerabilityId: v.id,
      },
    });
    await db.vaptVulnerability.update({ where: { id: v.id }, data: { promotedFindingId: finding.id } });
    console.log(`  + ${label} on ${v.asset.name} → NBE-22 corrective action (due ${new Date(v.dueAt ?? Date.now()).toISOString().slice(0, 10)})`);
  }

  // ── 5. Stamp scan summaries ──────────────────────────────────────────────
  console.log("── Scan summaries ──");
  for (const s of scans) {
    const vulns = await db.vaptVulnerability.findMany({ where: { scanId: s.id } });
    if (vulns.length === 0) continue;
    const summary = summariseVulns(vulns, now());
    await db.vaptScan.update({
      where: { id: s.id },
      data: {
        newCount: vulns.length,
        knownCount: 0,
        summary: JSON.stringify(summary),
      },
    });
  }

  const total = await db.vaptVulnerability.count();
  const kevCount = await db.vaptVulnerability.count({ where: { kev: true } });
  const promoted = await db.vaptVulnerability.count({ where: { promotedFindingId: { not: null } } });
  console.log(`\nDone. ${total} vulnerability record(s) (${kevCount} KEV), ${promoted} promoted into the Findings module.`);
  console.log("Live DAST demo: sign in as admin@cbe.com.et → VAPT Center → Scans → run FULL — the Adwa platform itself (http://localhost:3000) is a registered web target.");
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(() => db.$disconnect());
